/// <summary>
/// Creates a new instance of the <c>METRecalculateArrtibuteCacheController</c> class.
/// </summary>
/// <returns>
/// A new <c>METRecalculateArrtibuteCacheController</c> object.
/// </returns>
public static METRecalculateAttributeCacheController construct()
{
    return new METRecalculateAttributeCacheController();
}

/// <summary>
/// Defines caption.
/// </summary>
/// <returns>Caption</returns>
public ClassDescription defaultCaption()
{
    return "@MET:RecalculateArrtibuteCache";
}

/// <summary>
/// Executes the batch job.
/// </summary>
/// <param name = "_args">
/// <c>Args</c>.
/// </param>
public static void main(Args _args)
{
    METRecalculateAttributeCacheController controller = METRecalculateAttributeCacheController::construct();
    controller.parmArgs(_args);
    controller.startOperation();
}
